from selenium import webdriverfrom selenium.webdriver.chrome.options import Optionsfrom selenium.webdriver.common.by import Byfrom selenium.webdriver.support.ui import WebDriverWaitfrom selenium.webdriver.support import expected_conditions as ECimport timeprint("Router Wrapper")ROUTER_URL = "http://10.10.10.254"USERNAME = "YOUR_USERNAME"PASSWORD = "YOUR_PASSWORD"BROWSER_PATH = "/usr/bin/brave"# --- SIMPLE SETUP ---options = Options()options.binary_location = BROWSER_PATHoptions.add_argument("--headless=new") # Keep this commented out with a '#' so you can watch it run!options.add_argument("--disable-gpu")options.add_argument("--no-sandbox")options.add_argument("--disable-dev-shm-usage")print("Initializing Selenium...")driver = webdriver.Chrome(options=options)# Generous 20-second timeout to allow the router to loadwait = WebDriverWait(driver, 20)def force_click(by_type, selector):    """Waits for an element to exist in the HTML, then forces a click via JavaScript"""    # presence_of_element_located ignores if the button is currently invisible or animating    element = wait.until(EC.presence_of_element_located((by_type, selector)))    driver.execute_script("arguments[0].click();", element)    time.sleep(2) # Give the router 2 seconds to process the clicktry:    print("1. Navigating to router...")    driver.get(ROUTER_URL)    print("2. Logging in...")    wait.until(EC.presence_of_element_located((By.NAME, "Frm_Username"))).send_keys(USERNAME)    driver.find_element(By.NAME, "Frm_Password").send_keys(PASSWORD)    driver.find_element(By.ID, "LoginId").click()        # Wait a full 5 seconds for the heavy router dashboard to load    time.sleep(5)     print("3. Opening Hamburger Menu...")    force_click(By.CSS_SELECTOR, ".more-menu-icon.clickable")    print("4. Clicking Management & Diagnosis...")    force_click(By.ID, "mgrAndDiag")    print("5. Clicking System Management...")    force_click(By.ID, "devMgr")    print("6. Clicking Device Management...")    force_click(By.ID, "rebootAndReset")    print("7. Clicking Reboot...")    force_click(By.ID, "Btn_restart")    print("8. Confirming Reboot...")    force_click(By.ID, "confirmOK")    print("SUCCESS! Router is rebooting.")except Exception as e:    print(f"\n--- SCRIPT FAILED ---")    print(f"Error details: {e}")    # This will save a screenshot of exactly where it got stuck    driver.save_screenshot("router_error.png")    print("Saved a picture to 'router_error.png'. Open it to see what the script was looking at!")finally:    time.sleep(3)    driver.quit()